import pandas as pd
import re
import json
from datetime import datetime
import numpy as np

# Load data
csv_path = '/app/benchmark/data.csv'
df = pd.read_csv(csv_path)

# Data Cleaning
df['ECCENTRICITY'] = df['ECCENTRICITY'].astype(str).str.replace(r'^\.', '0.', regex=True).astype(float)
df['EPOCH'] = pd.to_datetime(df['EPOCH'])
df['Launch_Year'] = df['OBJECT_ID'].str[:4].astype(int)

# 1. KPIs
total_satellites = int(df.shape[0])
leo_count = int((df['MEAN_MOTION'] > 14).sum())
leo_share = (leo_count / total_satellites) * 100
starlink_count = int(df['OBJECT_NAME'].str.startswith('STARLINK').sum())
median_inclination = float(df['INCLINATION'].median())
launched_since_2020 = int((df['Launch_Year'] >= 2020).sum())
epoch_min = df['EPOCH'].min().strftime('%Y-%m-%d')
epoch_max = df['EPOCH'].max().strftime('%Y-%m-%d')

# 2. Orbital Regime Classification
def classify_orbit(row):
    if row['ECCENTRICITY'] > 0.25:
        return 'HEO'
    elif row['MEAN_MOTION'] > 14:
        return 'LEO'
    elif 0.9 <= row['MEAN_MOTION'] <= 1.05:
        return 'GEO'
    else:
        return 'MEO'

df['Orbit_Regime'] = df.apply(classify_orbit, axis=1)
orbit_counts = df['Orbit_Regime'].value_counts().to_dict()

# 3. Constellation Breakdown
def get_prefix(name):
    # Match letters and spaces at the start of the name, stopping at numbers or hyphens
    match = re.match(r'^([A-Z\s]+)', name)
    if match:
        return match.group(1).strip()
    return 'OTHER'

df['Constellation'] = df['OBJECT_NAME'].apply(get_prefix)
top_constellations = df['Constellation'].value_counts().head(10)
constellation_labels = top_constellations.index.tolist()
constellation_data = top_constellations.values.tolist()

# 4. Launch Trends
launch_trends = df['Launch_Year'].value_counts().sort_index()
launch_years = launch_trends.index.tolist()
launch_counts_data = launch_trends.values.tolist()

# 5. Orbital Parameters (Histograms)
# Inclination
inc_counts, inc_bins = np.histogram(df['INCLINATION'].dropna(), bins=36, range=(0, 180))
inc_labels = [f"{int(b)}-{int(inc_bins[i+1])}" for i, b in enumerate(inc_bins[:-1])]
inc_data = inc_counts.tolist()

# Mean Motion
mm_counts, mm_bins = np.histogram(df['MEAN_MOTION'].dropna(), bins=20, range=(0, 20))
mm_labels = [f"{int(b)}-{int(mm_bins[i+1])}" for i, b in enumerate(mm_bins[:-1])]
mm_data = mm_counts.tolist()

# Eccentricity
ecc_counts, ecc_bins = np.histogram(df['ECCENTRICITY'].dropna(), bins=10, range=(0, 1))
ecc_labels = [f"{b:.1f}-{ecc_bins[i+1]:.1f}" for i, b in enumerate(ecc_bins[:-1])]
ecc_data = ecc_counts.tolist()


